    'vec3 aniToon(vec3 alb, float lt){ float bL = aaStep(lt, uAnK.x), bM = aaStep(lt, uAnK.y); return mix(mix(alb * uAnShade, uAnShadeCol, 0.3), mix(alb * uAnMid, alb * uAnSun, bL), bM); }',
    // 没学的东西（峰、崖、雾里的头）：平的淡紫灰剪影，只带一点点面的明暗（读得出是立着的，不是贴纸）
    'vec3 aniSil(float ndl){ return uAnSil * (1.0 - 0.5 * uAnK2.x + uAnK2.x * smoothstep(-0.2, 0.7, ndl)); }',
    // 第 5 轮（评审第 3 次，艺术、学习者：今晚的彩层峡左柱边上挂着一排“水滴”）：骨架的今晚范围 fa 是外框的内切椭圆，外框四角的部件（彩层峡的左柱）落在椭圆外面，
    // 被当成没学的山盖上剪影；陡壁上按平面坐标取，椭圆的边成了一条条竖的淡紫。动画这边按外框本身（圆角的方框，同样的软边）认今晚，四角不上剪影
    'float aniTnBox(vec2 q){ if (uFocusAll.z <= 0.0) return 0.0; vec2 d = abs(q - uFocusAll.xy) / uFocusAll.zw; d *= d; return 1.0 - smoothstep(0.9, 1.15, sqrt(sqrt(d.x * d.x + d.y * d.y))); }',
    // 圆团的树：uv 一格一棵（按 dens 的概率），返回 (覆盖, 受光的一侧 0/1)；前面（屏幕上靠下）的树挡后面的
    'vec2 aniBlobs(vec2 uv, float dens){',
    '  vec2 g = floor(uv), fr = fract(uv); float cov = 0.0, lit = 0.0, best = -1e4, pw = max(fwidth(uv.x), 1e-4) * 0.9;',
    '  for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) {',
    '    vec2 c = g + vec2(float(i), float(j));',
    '    float on = step(hash(c + 27.7), dens);',
