    '    vec2 d = vec2(float(i), float(j)) + o - fr; d.y *= 0.92;',
    '    float r = 0.34 + 0.16 * hash(c + 5.3), dl = length(d);',
    '    float k = (1.0 - smoothstep(r - pw, r + pw, dl)) * on, dep = c.y + o.y;',
    '    if (k > 0.02 && dep > best) { best = dep; cov = max(cov, k); lit = smoothstep(-0.06, 0.06, (d.x * 0.62 + d.y * 0.78) / r - 0.12); }',
