    '    if (duskA) lit *= mix(uAnK.w, 1.0, smoothstep(uAnK.z, uAnK.z + 30.0, h + 12.0 * (pB - 0.5)));',
    '    float jit = 0.09 * (n2 - 0.5);',
    '    float bL = aaStep(lit + jit, uAnK.x), bM = aaStep(lit + jit, uAnK.y);',
    '    vec3 cS = mix(alb * uAnShade, uAnShadeCol, 0.3), cM = alb * uAnMid, cL = alb * uAnSun;',
    '    col = mix(cS, mix(cM, cL, bL), bM);',
