    '    float dens = aaStep(fbm(P / 34.0 + 3.0) + 0.35 * f, 0.6) * (1.0 - rockK) * (1.0 - snowK) * (1.0 - sandK) * (1.0 - smoothstep(0.2, 0.5, water)) * (1.0 - smoothstep(0.55, 0.7, f)) * step(0.5, learn);',
    '    vec2 tb = aniBlobs(sv / vec2(5.4, 4.6), dens * uAnK2.z);',
    '    if (tb.x > 0.0) {',
    '      float lv = bM + bL + tb.y - 1.0;',
    '      vec3 tS = mix(uAnForest * uAnShade, uAnShadeCol, 0.3), tM = uAnForest * uAnMid, tL = uAnForest * uAnSun;',
    '      vec3 tc = lv < 0.5 ? tS : lv < 1.5 ? tM : tL;',
