          B.box({ x: q.x, y: q.y, w: 17, d: 12, z: 3, h: 11, m: 0, part: i, fade: 1, hd: 1 });
          B.roof({ x: q.x, y: q.y, w: 23, d: 17, z: 14, h: 3.5, m: 1, part: i, hd: 1 });
