          B.roof({ x: q.x, y: q.y, w: 18, d: 14, z: 24.5, h: 3, m: 1, part: i, hd: 1 });
          B.box({ x: q.x, y: q.y, w: 10, d: 7.5, z: 26, h: 7, m: 0, part: i, hd: 1 });
