      ['s', 'n', 'w', 'e'].forEach(function (s) { B.box({ x: cx + (s === 'e' ? A * 0.9 : s === 'w' ? -A * 0.9 : 0), y: cy + (s === 's' ? Bd * 0.9 : s === 'n' ? -Bd * 0.9 : 0), w: 3, d: 3, h: 2, m: 2, struct: 'wall', side: s, fade: 1 }); });
