          [[-1, -1], [1, -1], [-1, 1], [1, 1]].forEach(function (c) { B.box({ x: head[0] + c[0] * 5, y: head[1] + c[1] * 4, w: 1.5, d: 1.5, zAbs: z0 + 1.4, h: PH, m: 3, part: i, hd: 1 }); });
          B.roof({ x: head[0], y: head[1], w: 21, d: 17, zAbs: z1, h: 3.2 * SB, m: 1, part: i, hd: 1 });
