        quayE: function (i) { quay(ePierX, i); },
        cargo: function (i, q) { var cx0 = sk.layout === 'cable' ? q.x - 4 : ePierX + 7, cy0 = sk.layout === 'cable' ? q.y : pyE + 11; [[0, 0, 0], [4, 0.5, 0], [2, 0.2, 1.4], [7.5, 0.4, 0]].forEach(function (o) { B.box({ x: cx0 + o[0], y: cy0 + o[1], z: o[2], w: 3.4, d: 3.4, h: 1.4, m: 7, part: i }); }); },
        // 骨架第 1 轮（缆渡 layout: 'cable'）：缆那头的登岸处（一小段码头加两根桩），缆本身挂在头上（两头各一根桩、中间一根细梁）
