            g.lineWidth = 0.8 + 0.7 * r2(); g.beginPath(); g.moveTo(q[0] - ca * L, q[1] - sa * L + 0.4); g.quadraticCurveTo(q[0] - sa * 1.1, q[1] + ca * 1.1 - 0.7, q[0] + ca * L, q[1] + sa * L + 0.4); g.stroke();
