          onBase(B, bb, { x: o0.x, y: o0.y + 3.2, w: 9, d: 1.6, h: 10, m: MAT.stele, part: i, mode: MODE.appearPart }, -1);
          onBase(B, bb, { x: o0.x, y: o0.y + 3.3, w: 4.4, d: 1.8, h: 4.8, m: MAT.steleHead, part: i, mode: MODE.appearPart }, 9);
