    params: { face: { min: -0.35, max: 0.35 }, lean: { min: -1.5, max: 1.5 }, small: { min: 0.85, max: 1.1 }, pose: { pick: ['up', 'tilt', 'sunk'] }, odd: { pick: [0, 0, 0, 1] } },
