      var onC = function (t) { return { x: ca[0] + (cb[0] - ca[0]) * t, y: ca[1] + (cb[1] - ca[1]) * t, ang: Math.atan2(cb[1] - ca[1], cb[0] - ca[0]) }; };
      bo = onC(0.35); bi = onC(0.65); bf = onC(0.5); onLoop = function (s2) { return onC(M.clamp(s2, 0.15, 0.85)); };
