    function inEncl(x, y) { var best = 0; encl.forEach(function (E) { var r = rotP(x - E.c[0], y - E.c[1], -rot), ax = Math.abs(r[0]) - E.w / 2, ay = Math.abs(r[1]) - E.d / 2; best = Math.max(best, ss(3, -7, Math.max(ax, ay) + 3 * n2(x / 9, y / 7, 633))); }); return best * (0.45 + 0.55 * M.fbm(x / 11, y / 9, 634, 2)); }
