      bbox: { x0: cx - a - 30, x1: cx + a + 30, y0: cy - b - 30, y1: cy + b + 30 }, anchorPart: 0, anchorXY: headE.st,
      area: function (x, y) { return eOf(x, y) < 1.1; }, mhBase: 5,
      mask: null,   // 合并第 2 轮：墙基围起来的那块暗地去掉（现代里读成一块地砖）
      fog: function (x, y) { var d = Math.hypot(x - headE.st[0], (y - headE.st[1]) * 1.2); return { cut: 0.9 * ss(18, 6, d), fill: 0 }; },
