      scale: 560, stretch: 1.25, wind: [6.0, 1.2], softTop: 0.05, softBot: 0.25, mist: 0.0, mistH: 10,
      erode: 0.14, detail: 1 / 90, topK: 1.0, eastK: 0, base: 0.22, top: 0.78, rel: 0.3, amb: 0.34, thr0: 0.75, thr1: 0.5,
